refentry.refsect1:
&reftitle.changelog;







     &Version;
     &Description;





     7.2.0
     यदि flags SORT_STRING हो भने, return गरिएको array नयाँ array मा unique elements थपेर बनाइन्छ; पहिले, यो array को एउटा copy हुन्थ्यो from जसबाट non-unique elements हटाइएका थिए। दुवैले एउटै keys अन्तर्गत एउटै elements राख्दछन्, तर यदि सबैभन्दा ठूलो integer key भएको element हटाइएकाहरूमध्ये पर्दछ भने, return गरिएको array मा append गरिएको element का लागि generate हुने index, array ले generate गर्ने भन्दा from फरक हुन्छ।

  &reftitle.examples;



    array_unique को उदाहरण


<?php

$input = ["a" => "green", "red", "b" => "green", "blue", "red"];
$result = array_unique($input);
print_r($result);

?>


    &example.outputs;


Array
(
    [a] => green
    [0] => red
    [1] => blue
)







    array_unique र types


<?php

$input = [4, "4", "3", 4, 3, "3"];
$result = array_unique($input);
var_dump($result);

?>


    &example.outputs;


array(2) {
  [0]=>
  int(4)
  [2]=>
  string(1) "3"
}
